pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract with 1 ether from deployer (already done via constructor)
        // Now fund caller and set block height
        address player = address(0x1234);
        vm.deal(player, 1 ether);
        // Warp to a specific block number so we can compute the answer
        vm.roll(100);
        // The guess is based on block.number + 1 for reference, +2 for buggy
        // For reference: block.number when lockInGuess is called = 100, answer = blockhash(101)
        // For buggy: answer = blockhash(102)
        // We'll compute the hash of blockhash(101) as the guess
        bytes32 hash = keccak256(abi.encodePacked(blockhash(101)));
        // player calls lockInGuess with that hash
        vm.prank(player);
        c.lockInGuess{value: 1 ether}(hash);
        // Now warp past the settlement block for reference
        vm.roll(102);
        // Try settle – this should succeed on buggy but not on reference
        // Since we cannot directly compare revert, we check balance
        uint256 balanceBefore = address(c).balance;
        vm.prank(player);
        // On reference: answer = blockhash(101) == guess, so transfer 2 ether (reverts if insufficient?), actually transfer succeeds
        // On buggy: answer = blockhash(102) != guess, so no transfer
        // Actually both succeed, but transfer only if guess matches
        // Let's check: reference with block.number+1: at roll(102), settle requires block.number > guesses[player].block, which is 101, so ok. answer = blockhash(101). guess = hash of blockhash(101) -> match -> transfer.
        // Buggy: guesses[player].block = 102, require block.number > 102? At roll(102), block.number == 102, not >, so revert.
        // So on reference settle succeeds, on buggy revert.
        // We'll use try/catch to detect revert
        bool ok;
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok); // this passes on reference (true) and fails on buggy (false)
    }
}

