pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testRegression_property() public {
        vm.deal(address(this), 3 ether);

        // Fund the contract with initial ether (constructor requires 1 ether)
        vm.deal(address(c), 1 ether); // already done via constructor payable
        // Actually, constructor already took msg.value of 1 ether from deployer. We need to give contract extra ether for payout.
        // The constructor receives 1 ether, but we need 2 ether for reward. So we send additional ether.
        vm.deal(address(this), 5 ether);
        payable(address(c)).transfer(2 ether);

        // msg.sender now has 3 ether left
        uint256 balanceBefore = address(this).balance;

        bytes32 guessHash = keccak256(abi.encodePacked(blockhash(block.number + 1)));
        // This guess is correct only if the blockhash matches when settle is called.
        // We'll lock in guess for block.number+1, but we need to know future blockhash.
        // Instead, use a known trick: mine a block, then compute hash of that block.

        // Simpler approach: We'll use vm.roll and vm.warp to control block number.
        // Lock guess for block number 2 (current block=1, so lock for block 2)
        vm.roll(1);
        bytes32 expectedHash = keccak256(abi.encodePacked(blockhash(2))); // future blockhash
        // But blockhash(2) is unknown at block 1; it's 0 until block 2 is mined.
        // Better: call lockInGuess, then mine to block after the target, then compute answer.

        // Let's do: lock for block 2, then mine to block 3, compute blockhash(2) to see if guess matched.
        // But at lock time block.number=1, so guess must match blockhash(2).
        // We can precompute: blockhash(2) is deterministic if we know the block's properties.
        // For simplicity, we'll do a known chain: 
        // After lockInGuess, vm.roll(2) then vm.roll(3) and compute blockhash(2).

        // Actually, the simplest: we lock a guess that we know is wrong and test that no transfer happens.
        // To trigger the divergence, we need a correct guess.
        // Let's do: 
        // 1. lockInGuess at block 1, targeting block 2.
        // 2. Set block to 2 (so blockhash(2) is defined but we don't know it).
        // 3. Compute blockhash(2) via vm.getBlockNumber? No — we can just compute from the hash of block 2's data.
        // Actually, vm.roll(N) does not produce a real blockhash. In tests, blockhash returns 0 for future blocks.
        // THIS IS A PROBLEM: we cannot control blockhash in a deterministic way.
        // 
        // Rethink: The test should work on a real network. Since we can't control blockhash, the best witness is:
        // The reward transfer of 2 ether vs 0 ether. We can still show that the caller's balance after settle() differs.
        // For ANY valid guess (correct or not), the reference tries to transfer 2 ether if correct, 0 if wrong.
        // But the bug always transfers 0 when correct. So if we make a correct guess, reference transfers 2, bug transfers 0.
        // 
        // We can create a scenario where the guess is correct by using a known blockhash:
        // - At block 1, lockInGuess with the hash of block 2 (which we don't know yet). But we can vm.roll to block 2, then compute blockhash(2), then revert to block 1.
        // But vm.roll changes block.number without changing blockhash? Actually blockhash is computed from block data.
        // In Forge tests, blockhash(block.number) returns a known constant (0x...). For past blocks, it returns 0.
        // 
        // Alternative: The difference is also in the state variable 'settle' — there is no such variable. The difference is in the transfer.
        // Since the previous attempts with balance checks were rejected, we need a different observable.
        // What about checking if settle() reverts? Both versions revert under same conditions.
        // The only difference is the amount transferred. Since we can't easily make a correct guess, maybe we can check the contract's balance?
        // After settle with a correct guess, reference sends 2 ether out, bug sends 0. So c.balance differs.
        // 
        // We can engineer a correct guess: 
        // Step 1: vm.roll(2). At block 2, compute blockhash(2) = keccak256(abi.encodePacked(blockhash(2))). But blockhash(2) at block 2 is a known value?
        // Actually at block 2, blockhash(2) returns the hash of block 2. We can snapshot that.
        // Step 2: vm.roll(1). Now lock guess equal to that hash.
        // Step 3: vm.roll(3). Now settle — block.number > 2, and answer = blockhash(2) which we saved.
        // But blockhash(2) at block 3 is still the hash of block 2. So guess matches answer.

        vm.roll(2);
        bytes32 answer = keccak256(abi.encodePacked(blockhash(2)));
        vm.roll(1);

        vm.prank(address(this));
        c.lockInGuess{value: 1 ether}(answer);

        vm.roll(3);
        vm.prank(address(this));
        c.settle();

        uint256 balanceAfter = address(this).balance;

        // In reference, we gain 2 ether (balance increases by 2). In bug, we gain 0 (balance unchanged).
        assertTrue(balanceAfter == balanceBefore + 2 ether, "balance not increased by 2");
    }
}

