pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the test contract and then deploy C with 1 ether
        vm.deal(address(this), 10 ether);
        // We already deployed c with 1 ether in setUp, so now fund it from here
        // Actually, the constructor requires msg.value = 1 ether; we need to send ether on deploy
        // Re-deploy with value? No, setUp already used new C() which requires msg.value... But in Forge, constructor is called without value by default.
        // To fix, we must fund the contract after deploy; but contract already has 1 ether if we sent it. Let's ensure the test contract has ether and send to c if needed.
        // Simpler approach: use a separate account as actor.
        address alice = address(0x1234);
        vm.deal(alice, 10 ether);
        // Alice calls lockInGuess with 1 ether
        vm.prank(alice);
        c.lockInGuess{value: 1 ether}(keccak256(abi.encodePacked(blockhash(block.number + 1))));
        // Warp past the target block
        vm.roll(block.number + 2);
        // Alice settles
        uint256 balanceBefore = alice.balance;
        vm.prank(alice);
        c.settle();
        uint256 balanceAfter = alice.balance;
        // Reference: balanceAfter = balanceBefore + 2 ether (since 2 ether transferred)
        // Bug:     balanceAfter = balanceBefore + 0 ether (transfer of 0)
        assertTrue(balanceAfter > balanceBefore);
    }
}

