pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Give Alice enough ether
        address alice = address(0x1234);
        vm.deal(alice, 10 ether);

        // Alice funds the contract with 1 ether during construction
        // Already done in setUp by deploying C with 1 ether
        // This contract already has 1 ether from constructor
        // Then Alice locks her guess with 1 ether
        vm.prank(alice);
        c.lockInGuess{value: 1 ether}(keccak256(abi.encodePacked(blockhash(0))));

        // Move to the next block so settle can be called
        vm.roll(block.number + 2);

        // Record Alice's balance before settle
        uint256 balanceBefore = alice.balance;

        // Alice settles
        vm.prank(alice);
        c.settle();

        uint256 balanceAfter = alice.balance;

        // In reference, Alice receives 2 ether (net gain of 1 ether since she paid 1 ether for locking)
        // In buggy, Alice receives 0 ether (net loss of 1 ether)
        assertTrue(balanceAfter == balanceBefore + 2 ether);
    }
}
